{
  "interpretation": {
    "name": "TightenVariantFastenersLine2AndReturnTool",
    "scope": {"line": 2, "station": "st2", "tool": "NR7", "variant": "F30"},
    "goal": "Tighten the fasteners of variant F30 at station st2 of line 2 with the shared nutrunner NR7, evaluate and record the result, and return the tool to the crib so other lines are not blocked.",
    "constraints": [
      "The tool must be reserved before use, and the lease must be renewed before every tool-using Step",
      "The tool must be at the station before configure-tool and tighten-fasteners",
      "The tightening program must come from get-program and never appear as literals",
      "The tightening must be evaluated and recorded for traceability",
      "transport-tool must be delegated to agvexecutor",
      "The tool must be returned to the crib and the reservation released after use"
    ],
    "preference": "Release the tool as early as possible so that other lines are not blocked",
    "priority": "normal",
    "horizon": "single execution, now",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "line2-f30-tightening-with-tool-return",
    "first_action": "Prepare",
    "actions": [
      {
        "name": "Prepare",
        "next": "Deliver",
        "steps": [
          {"name": "reserve", "service": "reserve-tool", "next": [], "dep": [], "executor": null, "params": {}},
          {"name": "program", "service": "get-program", "next": [], "dep": [], "executor": null, "params": {}}
        ]
      },
      {
        "name": "Deliver",
        "next": "Tighten",
        "steps": [
          {"name": "to-station", "service": "transport-tool", "next": [], "dep": ["reserve"], "executor": "agvexecutor", "params": {"to": "station"}}
        ]
      },
      {
        "name": "Tighten",
        "next": "Finish",
        "steps": [
          {"name": "configure", "service": "configure-tool", "next": ["tighten"], "dep": ["program", "reserve", "to-station"], "executor": null, "params": {}},
          {"name": "tighten", "service": "tighten-fasteners", "next": [], "dep": ["configure", "reserve", "to-station"], "executor": null, "params": {}}
        ]
      },
      {
        "name": "Finish",
        "next": null,
        "steps": [
          {"name": "to-crib", "service": "transport-tool", "next": ["release"], "dep": ["reserve", "tighten"], "executor": "agvexecutor", "params": {"to": "crib"}},
          {"name": "release", "service": "release-tool", "next": [], "dep": ["reserve", "to-crib"], "executor": null, "params": {}},
          {"name": "evaluate", "service": "evaluate-tightening", "next": [], "dep": ["tighten", "program"], "executor": null, "params": {}},
          {"name": "record", "service": "record-tightening", "next": [], "dep": ["tighten"], "executor": null, "params": {}}
        ]
      }
    ]
  }
}
